<script setup lang="ts">
import {computed,ref,shallowRef,watch} from 'vue';
import {componentFields} from '../shared/component-fields';
import {mdiClose} from '@mdi/js';
import type {Database,Specs} from '../shared/types';
import type {ComponentMergeInput,ComponentMergePreview} from '../shared/component-merge';
const props=defineProps<{sourceIds:string[]|null;db:Database;revision:string}>();
const emit=defineEmits<{close:[];reload:[];notify:[message:string]}>();
const draft=ref<ComponentMergeInput|null>(null),preview=ref<ComponentMergePreview|null>(null),busy=ref(false),error=ref('');
const opener=shallowRef<HTMLElement|null>(null);
function restoreFocus(){if(opener.value?.isConnected)opener.value.focus();else document.getElementById('main-content')?.focus();}
let expected='',original='';
watch(()=>props.sourceIds,ids=>{if(ids&&document.activeElement instanceof HTMLElement)opener.value=document.activeElement;draft.value=ids?{sourceIds:[...ids],targetId:'',notes:''}:null;expected=props.revision;original=JSON.stringify(draft.value);preview.value=null;error.value='';},{immediate:true});
watch(draft,()=>preview.value=null,{deep:true});
const sources=computed(()=>props.db.components.filter(c=>draft.value?.sourceIds.includes(c.id)));
const choices=computed(()=>props.db.components.map(c=>({title:`${c.name} (${c.id})`,value:c.id})));
const targets=computed(()=>props.db.components.filter(c=>!draft.value?.sourceIds.includes(c.id)&&(!sources.value.length||sources.value.every(s=>s.category===c.category))).map(c=>({title:`${c.name} (${c.id})`,value:c.id})));
const fieldLabel=(key:string)=>preview.value?componentFields(preview.value.target).find(field=>field.key===key)?.label||key.replace(/([A-Z])/g,' $1'):key;
const specification=(specs:Specs,key:string)=>JSON.stringify(specs[key as keyof Specs])??'Unknown';
function hasUnsavedChanges(){return busy.value||!!draft.value&&JSON.stringify(draft.value)!==original;}
function confirmDiscard(){if(busy.value)return false;if(hasUnsavedChanges()&&!window.confirm('Discard the component merge selection?'))return false;emit('close');return true;}
defineExpose({hasUnsavedChanges,confirmDiscard});
async function request(apply=false){if(busy.value||!draft.value)return;busy.value=true;error.value='';try{const response=await fetch(`/api/catalog/merge/${apply?'apply':'preview'}`,{method:'POST',headers:{'Content-Type':'application/json','If-Match':expected},body:JSON.stringify(apply?{input:draft.value,token:preview.value?.token}:draft.value)});const body=await response.json();if(!response.ok)throw Error(body.error||'Merge failed.');if(apply){emit('reload');emit('notify','Component types merged. Review affected configurations and installed-PC compatibility.');emit('close');}else{preview.value=body;expected=response.headers.get('X-Workspace-Revision')||expected;}}catch(e){error.value=e instanceof Error?e.message:String(e);preview.value=null;}finally{busy.value=false;}}
</script>
<template><v-dialog :activator="opener||undefined" :open-on-click="false" @after-leave="restoreFocus" :model-value="!!draft" scrollable persistent max-width="1000" aria-labelledby="component-merge-title" @keydown.esc.stop.prevent="confirmDiscard"><v-card v-if="draft" class="editor-dialog"><v-card-title class="dialog-head"><h2 id="component-merge-title">Merge component types</h2><v-btn :icon="mdiClose" variant="text" aria-label="Close component merge" :disabled="busy" @click="confirmDiscard" /></v-card-title><v-card-text class="dialog-body" :inert="busy"><v-alert v-if="error" type="error" role="alert" class="mb-4">{{error}}</v-alert><p>Choose duplicate catalog records and the canonical type to keep. Its specifications remain authoritative. Physical stock records remain separate.</p><div class="control-stack mt-4"><v-autocomplete v-model="draft.sourceIds" label="Duplicate component types" :items="choices" multiple chips closable-chips clearable @update:model-value="v=>draft!.sourceIds=v||[]" /><v-autocomplete v-model="draft.targetId" label="Canonical component type to keep" :items="targets" clearable /><v-textarea v-model="draft.notes" label="Correction reason" rows="2" /><v-btn variant="outlined" :disabled="!draft.sourceIds.length||!draft.targetId||busy" :loading="busy" @click="request()">Preview merge</v-btn></div><section v-if="preview" class="control-stack mt-5"><h3>Keep {{preview.target.name}}</h3><section v-for="source in preview.sources" :key="source.id"><p>Remove {{source.name}} ({{source.id}}) · {{source.manufacturer||'Manufacturer unknown'}}.</p><details v-if="source.differentSpecs.length"><summary>Compare {{source.differentSpecs.length}} specification differences</summary><v-table v-table-scroll><caption class="sr-only">{{source.name}} compared with {{preview.target.name}}</caption><thead><tr><th>Field</th><th>Duplicate</th><th>Canonical value kept</th></tr></thead><tbody><tr v-for="key in source.differentSpecs" :key="key"><td>{{fieldLabel(key)}}</td><td><code>{{specification(source.specs,key)}}</code></td><td><code>{{specification(preview.target.specs,key)}}</code></td></tr></tbody></v-table></details><p v-else>No specification differences.</p></section><p>{{preview.configurations.length}} configurations · {{preview.inventory.length}} stock records · {{preview.pcs.length}} PCs · {{preview.transitionPlans}} saved transition plans</p><details v-if="preview.configurations.length"><summary>Configurations to review</summary><ul><li v-for="cfg in preview.configurations" :key="cfg.id">{{cfg.name}} ({{cfg.id}})</li></ul></details><details v-if="preview.inventory.length"><summary>Stock records to reclassify</summary><ul><li v-for="stock in preview.inventory" :key="stock.id">{{stock.identity}} · {{stock.quantity}} unit(s) · {{stock.id}}</li></ul></details><v-alert type="info" variant="tonal"><p v-for="warning in preview.warnings" :key="warning">{{warning}}</p></v-alert></section></v-card-text><v-card-actions class="dialog-footer"><v-btn variant="text" :disabled="busy" @click="confirmDiscard">Cancel</v-btn><v-btn color="primary" :disabled="!preview||busy" :loading="busy" @click="request(true)">Merge into canonical type</v-btn></v-card-actions></v-card></v-dialog></template>
